# Détection dynamique et automatique de l'adresse IP locale sur le réseau de l'usine
def obtenir_ip_locale():
    candidate_ips = []
    try:
        # Sonde UDP sans émission de paquet réel pour récupérer l'interface sortante Wi-Fi
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.connect(('10.20.33.254', 80))
        candidate_ips.append(s.getsockname()[0])
        s.close()
    except Exception:
        pass
    try:
        hostname = socket.gethostname()
        for ip in socket.gethostbyname_ex(hostname)[2]:
            candidate_ips.append(ip)
    except Exception:
        pass
    
    # 1. Priorité absolue au sous-réseau Wi-Fi usine (10.20.x.x)
    for ip in candidate_ips:
        if ip.startswith("10.20."):
            return ip
    # 2. Autre réseau privé local (hors VPN Barracuda 100.x et loopback)
    for ip in candidate_ips:
        if ip.startswith("10.") and not ip.startswith("100."):
            return ip
        if ip.startswith("192.168."):
            return ip
        if ip.startswith("172.") and not ip.startswith("127."):
            return ip
    return "10.20.33.82"

IP_RESEAU_LOCALE = obtenir_ip_locale()
URL_RESEAU_EQUIPE = f"http://{IP_RESEAU_LOCALE}:8501"


# Fonction pour éliminer les caractères illégaux que openpyxl refuse de transcrire

# Fonction de conversion sécurisée en entier (gère les NaN, None, floats sans lever de ValueError)
def safe_int(val, default=0):
    if pd.isna(val) or val is None or str(val).strip() in ['', 'nan', 'None']:
        return default
    try:
        return int(float(str(val).replace(',', '.').strip()))
    except Exception:
        return default

def clean_for_excel(val):
    if pd.isna(val) or val is None:
        return ""
    if isinstance(val, str):
        # Supprime tous les caractères de contrôle non autorisés en XML/Excel (\x00-\x08, \x0b-\x0c, \x0e-\x1f)
        return re.sub(r'[\x00-\x08\x0b-\x0c\x0e-\x1f]', '', val)
    return val

# Fonction intelligente de sélection par défaut sur la date du jour ou la date active
def trouver_index_date_du_jour(liste_options):
    if not liste_options:
        return 0
    # 1. Si une date globale a déjà été sélectionnée par l'utilisateur
    if "global_selected_date" in st.session_state and st.session_state["global_selected_date"] in liste_options:
        return liste_options.index(st.session_state["global_selected_date"])
    # 2. Si aujourd'hui est dans la liste
    d_now = datetime.now()
    today_patterns = [
        d_now.strftime("%d/%m/%Y"),
        f"{d_now.day}/{d_now.month:02d}/{d_now.year}",
        f"{d_now.day:02d}/{d_now.month}/{d_now.year}",
        f"{d_now.day}/{d_now.month}/{d_now.year}",
        d_now.strftime("%Y-%m-%d")
    ]
    for idx, opt in enumerate(liste_options):
        s = str(opt).strip()
        if any((tp == s or tp in s) for tp in today_patterns):
            return idx
    # 3. Préférer la première vraie date avec des données plutôt que "Toutes"
    for idx, opt in enumerate(liste_options):
        if str(opt) not in ["Toutes", "Non spécifiée", "🌟 Toutes les dates"]:
            return idx
    return 0

def sort_dates(dates_list):
    try:
        clean_d = [str(d).strip() for d in dates_list if d and str(d).strip() != "" and str(d) != "Non spécifiée"]
        # Trier chronologiquement (plus récentes en premier)
        sorted_d = sorted(clean_d, key=lambda x: pd.to_datetime(x, format="%d/%m/%Y", errors="coerce") or pd.Timestamp.min, reverse=True)
        if "Non spécifiée" in dates_list:
            sorted_d.append("Non spécifiée")
        return sorted_d
    except:
        return sorted(dates_list, reverse=True)

# Fonction d'extraction de date propre (DD/MM/YYYY)
def extract_date(date_str):
    if not date_str or pd.isna(date_str) or str(date_str).strip() == "":
        return "Non spécifiée"
    m_date = re.search(r'(\d{1,2}/\d{1,2}/\d{4})', str(date_str))
    if m_date:
        return m_date.group(1)
    parts = str(date_str).split()
    if len(parts) > 0 and "/" in parts[0]:
        return parts[0]
    return "Non spécifiée"

# Fonction de nettoyage et conversion numérique
def clean_numeric(val):
    if pd.isna(val):
        return 0.0
    val_str = str(val).replace('\xa0', '').replace(' ', '').replace(',', '.').strip()
    match = re.search(r'([\d\.]+)', val_str)
    if match:
        try:
            return float(match.group(1))
        except:
            return 0.0
    return 0.0

# Fonction d'extraction du descriptif (Boîtes, Europe, Europe 15)
def parse_description(desc):
    desc = str(desc).strip()
    qty_boites = 0
    qty_europe = 0
    qty_europe15 = 0
    
    # Séparer par sauts de ligne réels ou balises HTML
    lines = re.split(r'\n|<br/?>', desc, flags=re.IGNORECASE)
    for line in lines:
        line = line.strip()
        if not line:
            continue
        
        # Recherche de motifs comme '36 Palettes/Palets', '7 Palettes', etc.
        m_qty = re.search(r'(\d+)\s*(?:Palettes/Palets|Palettes|Palets|pal|palettes|palets)', line, re.IGNORECASE)
        qty = int(m_qty.group(1)) if m_qty else None
        
        # Motifs alternatifs
        if qty is None:
            m_qty2 = re.search(r'(\d+)\s+BOITES', line, re.IGNORECASE)
            if m_qty2: qty = int(m_qty2.group(1))
        if qty is None:
            m_qty3 = re.search(r'BOITES\s+(\d+)', line, re.IGNORECASE)
            if m_qty3: qty = int(m_qty3.group(1))
        if qty is None:
            m_qty4 = re.search(r'(\d+)\s+pal\s+boites', line, re.IGNORECASE)
            if m_qty4: qty = int(m_qty4.group(1))
        if qty is None:
            m_qty5 = re.search(r'(\d+)\s+pal\s+europe', line, re.IGNORECASE)
            if m_qty5: qty = int(m_qty5.group(1))
            
        if qty is not None:
            # Classification par type de palette
            if '1420X1120' in line or 'BOITES' in line.upper() or 'BOTES' in line.upper() or 'boites' in line.lower():
                qty_boites += qty
            elif any(x in line.upper() for x in ['NIMP15', 'TRAITEE', 'NIMP 15', 'ROSE']):
                qty_europe15 += qty
            elif 'EUROPE' in line.upper() or 'EUR' in line.upper():
                qty_europe += qty
            else:
                # Si format de palette 1420x1120 sans mention explicite
                if '1420X1120' in line or '1420 x 1120' in line:
                    qty_boites += qty
                else:
                    qty_europe += qty
        else:
            # Règle pour '40 pal boites' sans motif d'unité
            if '40 pal boites' in line.lower():
                qty_boites += 40
            elif 'botes' in line.lower() or 'boites' in line.lower():
                num_match = re.search(r'(\d+)', line)
                if num_match:
                    qty_boites += int(num_match.group(1))
                    
    return (
        qty_europe if qty_europe > 0 else None,
        qty_europe15 if qty_europe15 > 0 else None,
        qty_boites if qty_boites > 0 else None
    )

# Traiter le fichier importé et extraire l'intégralité des colonnes
def process_data(df_raw):
    rows_live = []
    
    # Identifier les en-têtes
    headers = [str(col).strip() for col in df_raw.columns]
    
    # Trouver l'index de chaque colonne requise de façon souple
    def get_col_index(possible_names):
        for name in possible_names:
            for idx, col in enumerate(headers):
                if col.lower().strip() == name.lower().strip():
                    return idx
        return -1
        
    col_ref = get_col_index(["Ref", "Référence", "Reference"])
    col_type = get_col_index(["Type"])
    col_desc = get_col_index(["Descriptif", "Description"])
    col_trans = get_col_index(["Transporteur"])
    col_dest = get_col_index(["Expéditeur/Destinataire", "Expediteur/Destinataire", "Destinataire", "Expéditeur"])
    col_statut = get_col_index(["Statut"])
    col_date_resa = get_col_index(["Date Réservation", "Date Reservation", "Date Résa"])
    
    # Nouvelles colonnes requises
    col_date_ch_dech = get_col_index(["Date Chargement/Dechargement", "Date Chargement", "Dechargement"])
    col_date_exp_livr = get_col_index(["Date Expédition/Livraison", "Date Expédition", "Date Livraison"])
    col_util_resa = get_col_index(["Utilisateur de réservation", "Utilisateur"])
    col_date_depart = get_col_index(["Date départ", "Date depart"])
    col_heure_depart = get_col_index(["Heure départ", "Heure depart"])
    col_poids = get_col_index(["Poids", "Poids (kg)"])
    col_adr1 = get_col_index(["Adresse 1"])
    col_adr2 = get_col_index(["Adresse 2"])
    col_cp = get_col_index(["Code Postal", "CP"])
    col_ville = get_col_index(["Ville"])
    col_inst = get_col_index(["Instruction", "Instructions"])
    col_cout = get_col_index(["Coût Transport", "Cout Transport", "Coût", "Cout"])

    for idx, row in df_raw.iterrows():
        # Ignorer les lignes vides
        if row.isna().all() or str(row.values[0]).strip() == "":
            continue
            
        ref = str(row.iloc[col_ref]).strip() if col_ref != -1 and not pd.isna(row.iloc[col_ref]) else ""
        
        # Extraction du numéro d'expédition
        num_exp = "RESA MANUELLE"
        if ref:
            m = re.match(r'^(\d+)', ref)
            if m:
                num_exp = m.group(1)
                
        # Type
        type_val = str(row.iloc[col_type]).strip() if col_type != -1 and not pd.isna(row.iloc[col_type]) else ""
        
        # Descriptif et parsing des palettes
        desc_val = str(row.iloc[col_desc]).strip() if col_desc != -1 and not pd.isna(row.iloc[col_desc]) else ""
        qty_eur, qty_eur15, qty_boi = parse_description(desc_val)
        
        # Calcul du total Europe
        total_eur = (qty_eur or 0) + (qty_eur15 or 0)
        
        # Destination, Transporteur, Statut
        dest_val = str(row.iloc[col_dest]).strip() if col_dest != -1 and not pd.isna(row.iloc[col_dest]) else ""
        trans_val = str(row.iloc[col_trans]).strip() if col_trans != -1 and not pd.isna(row.iloc[col_trans]) else ""
        stat_val = str(row.iloc[col_statut]).strip() if col_statut != -1 and not pd.isna(row.iloc[col_statut]) else ""
        
        # Détection automatique de colis / conteneur (ex: 1044 colis ou colis en vrac)
        is_conteneur = any(k in desc_val.lower() for k in ["colis", "cls", "carton", "conteneur"]) or any(k in trans_val.lower() for k in ["conteneur", "container"])
        nb_colis_val = ""
        m_colis = re.search(r'(\d+)\s*(?:colis|carton|cartons|cls|pieces|pcs)', desc_val, re.IGNORECASE)
        if m_colis:
            nb_colis_val = f"{m_colis.group(1)} colis"
        else:
            if is_conteneur:
                nb_colis_val = "colis vrac"
        if is_conteneur and not trans_val.startswith("🚢"):
            trans_val = f"🚢 {trans_val} (Conteneur)" 
        
        # Horaire et Clé de Tri depuis la Date de Réservation (Arrondi à l'heure ronde HH:00 sans les minutes)
        horaire = "00:00"
        tri = 9999
        date_resa_val = str(row.iloc[col_date_resa]).strip() if col_date_resa != -1 and not pd.isna(row.iloc[col_date_resa]) else ""
        
        m_time = re.search(r'(\d{1,2}):(\d{2})', date_resa_val)
        if m_time:
            hh = m_time.group(1).zfill(2)
            horaire = f"{hh}:00"
            # Les horaires 00:00 sont envoyés à la fin par défaut (tri = 9999)
            if hh == "00":
                tri = 9999
            else:
                tri = int(hh + "00")
            
        # Données additionnelles demandées
        date_ch_dech_val = str(row.iloc[col_date_ch_dech]).strip() if col_date_ch_dech != -1 and not pd.isna(row.iloc[col_date_ch_dech]) else ""
        date_exp_livr_val = str(row.iloc[col_date_exp_livr]).strip() if col_date_exp_livr != -1 and not pd.isna(row.iloc[col_date_exp_livr]) else ""
        util_resa_val = str(row.iloc[col_util_resa]).strip() if col_util_resa != -1 and not pd.isna(row.iloc[col_util_resa]) else ""
        date_depart_val = str(row.iloc[col_date_depart]).strip() if col_date_depart != -1 and not pd.isna(row.iloc[col_date_depart]) else ""
        heure_depart_val = str(row.iloc[col_heure_depart]).strip() if col_heure_depart != -1 and not pd.isna(row.iloc[col_heure_depart]) else ""
        
        poids_val = clean_numeric(row.iloc[col_poids]) if col_poids != -1 else 0.0
        cout_val = clean_numeric(row.iloc[col_cout]) if col_cout != -1 else 0.0
        
        adr1_val = str(row.iloc[col_adr1]).strip() if col_adr1 != -1 and not pd.isna(row.iloc[col_adr1]) else ""
        adr2_val = str(row.iloc[col_adr2]).strip() if col_adr2 != -1 and not pd.isna(row.iloc[col_adr2]) else ""
        cp_val = str(row.iloc[col_cp]).strip() if col_cp != -1 and not pd.isna(row.iloc[col_cp]) else ""
        ville_val = str(row.iloc[col_ville]).strip() if col_ville != -1 and not pd.isna(row.iloc[col_ville]) else ""
        inst_val = str(row.iloc[col_inst]).strip() if col_inst != -1 and not pd.isna(row.iloc[col_inst]) else ""
        
        # Extraction de la Date d'Opération (priorité Date Chg/Dech, sinon Réservation, Expédition, Départ)
        date_op = extract_date(date_ch_dech_val)
        if date_op == "Non spécifiée":
            date_op = extract_date(date_resa_val)
        if date_op == "Non spécifiée":
            date_op = extract_date(date_exp_livr_val)
        if date_op == "Non spécifiée":
            date_op = extract_date(date_depart_val)
        if date_op == "Non spécifiée":
            # Si aucune date n'est précisée dans cette ligne (ex: fichier live journalier), attribuer la date du jour
            date_op = datetime.now().strftime("%d/%m/%Y")
        
        ref_key = ref if ref else f"ID_{idx}"
        rows_live.append({
            "REF_KEY": ref_key,
            "NUMERO EXPEDITION": num_exp,
            "TYPE": type_val,
            "Caisses": "",
            "EUROPE": total_eur if total_eur > 0 else (qty_eur if qty_eur else None),
            "EUROPE_STD": qty_eur,
            "EUROPE_15": qty_eur15,
            "Total EUROPE": total_eur,
            "BOITES": qty_boi,
            "DESTINATION": dest_val,
            "TRANSPORTEUR": trans_val,
            "STATUT": stat_val,
            "Tri": tri,
            "HORAIRE": horaire,
            "DATE_OP": date_op,
            "IS_CONTENEUR": is_conteneur, "NB_COLIS": nb_colis_val,
            
            # Champs logistiques et administratifs
            "Date Chargement/Dechargement": date_ch_dech_val,
            "Date Expédition/Livraison": date_exp_livr_val,
            "Utilisateur de réservation": util_resa_val,
            "Date Réservation": date_resa_val,
            "Date départ": date_depart_val,
            "Heure départ": heure_depart_val,
            "Poids": poids_val,
            "Adresse 1": adr1_val,
            "Adresse 2": adr2_val,
            "Code Postal": cp_val,
            "Ville": ville_val,
            "Instruction": inst_val,
            "Coût Transport": cout_val,
            
            # Assignation prévisionnelle
            "CARISTE_ASSIGNE": "Non assigné",
            "QUAI_CONSIGNE": "",
            
            # Checkboxes de suivi
            "TROUVÉE": False,
            "ANOMALIE_CHECK": False,
            "OK": False,
            "NOK": False,
            "ANOMALIE": "",
            "GESTIONNAIRE": "",
            "MODIFIE_PAR": "",
            "DATE_HEURE_MODIF": ""
        })
        
    df_live = pd.DataFrame(rows_live)
    if not df_live.empty:
        df_live = df_live.sort_values(by=["Tri", "HORAIRE"]).reset_index(drop=True)
    return df_live

