def charger_caristes():
    if os.path.exists(SHARED_CARISTES_FILE):
        try:
            with open(SHARED_CARISTES_FILE, "r", encoding="utf-8") as f:
                c_list = json.load(f)
                if isinstance(c_list, list) and len(c_list) > 0:
                    if "Non assigné" not in c_list:
                        c_list = ["Non assigné"] + [c for c in c_list if c != "Non assigné"]
                    return c_list
        except Exception:
            return DEFAULT_CARISTES
    return DEFAULT_CARISTES

def sauvegarder_caristes(c_list):
    try:
        clean_list = []
        for c in c_list:
            c_str = str(c).strip()
            if c_str and c_str not in clean_list:
                clean_list.append(c_str)
        if "Non assigné" not in clean_list:
            clean_list = ["Non assigné"] + clean_list
        with open(SHARED_CARISTES_FILE, "w", encoding="utf-8") as f:
            json.dump(clean_list, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False

