def charger_postes():
    if os.path.exists(SHARED_POSTES_FILE):
        try:
            with open(SHARED_POSTES_FILE, "r", encoding="utf-8") as f:
                p_list = json.load(f)
                if isinstance(p_list, list) and len(p_list) > 0:
                    return p_list
        except Exception:
            return DEFAULT_POSTES
    return DEFAULT_POSTES

def sauvegarder_postes(p_list):
    try:
        clean_list = []
        for p in p_list:
            p_str = str(p).strip()
            if p_str and p_str not in clean_list:
                clean_list.append(p_str)
        with open(SHARED_POSTES_FILE, "w", encoding="utf-8") as f:
            json.dump(clean_list, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False

LISTE_MISSIONS_TYPES = charger_postes()

def charger_missions():
    if os.path.exists(SHARED_MISSIONS_FILE):
        try:
            with open(SHARED_MISSIONS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                for k, v in DEFAULT_MISSIONS.items():
                    if k not in data:
                        data[k] = v
                return data
        except Exception:
            return DEFAULT_MISSIONS
    else:
        try:
            with open(SHARED_MISSIONS_FILE, "w", encoding="utf-8") as f:
                json.dump(DEFAULT_MISSIONS, f, ensure_ascii=False, indent=2)
        except Exception:
            pass
        return DEFAULT_MISSIONS

def sauvegarder_missions(missions_dict):
    try:
        with open(SHARED_MISSIONS_FILE, "w", encoding="utf-8") as f:
            json.dump(missions_dict, f, ensure_ascii=False, indent=2)
    except Exception:
        pass


