def modifier_camion_cariste(ref_key, action, cariste=None, motif=""):
    try:
        now_str = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
        op_name = st.session_state.get("auth_user", "Cariste")
        df_target = st.session_state.processed_data.copy()
        
        mask = (df_target["REF_KEY"].astype(str) == str(ref_key))
        if not mask.any():
            return False
            
        transp = str(df_target.loc[mask, "TRANSPORTEUR"].values[0])
        num_exp = str(df_target.loc[mask, "NUMERO EXPEDITION"].values[0])
        
        if action == "take":
            df_target.loc[mask, "CARISTE_ASSIGNE"] = cariste
            enregistrer_action_journal(cariste, "Prise en charge", f"🚚 {cariste} a pris en charge le camion {transp} (Expéd {num_exp})", icone="🚚", importance="normal")
        elif action == "release":
            df_target.loc[mask, "CARISTE_ASSIGNE"] = "Non assigné"
            df_target.loc[mask, "TROUVÉE"] = False
            df_target.loc[mask, "OK"] = False
            df_target.loc[mask, "NOK"] = False
            df_target.loc[mask, "ANOMALIE_CHECK"] = False
            enregistrer_action_journal(op_name, "Annulation affectation", f"❌ {op_name} a libéré le camion {transp} (Expéd {num_exp})", icone="❌", importance="normal")
        elif action == "trouve":
            df_target.loc[mask, "TROUVÉE"] = True
            df_target.loc[mask, "OK"] = False
            df_target.loc[mask, "NOK"] = False
            df_target.loc[mask, "ANOMALIE_CHECK"] = False
            enregistrer_action_journal(op_name, "Commande Trouvée", f"🟡 Trouvée : Expéd {num_exp} ({transp})", icone="🟡", importance="succes")
        elif action == "ok":
            df_target.loc[mask, "OK"] = True
            df_target.loc[mask, "TROUVÉE"] = False
            df_target.loc[mask, "NOK"] = False
            df_target.loc[mask, "ANOMALIE_CHECK"] = False
            enregistrer_action_journal(op_name, "Pointage Conforme", f"🟢 OK validé sur Expéd {num_exp} ({transp})", icone="🟢", importance="succes")
        elif action == "anomalie":
            df_target.loc[mask, "ANOMALIE_CHECK"] = True
            df_target.loc[mask, "ANOMALIE"] = motif
            df_target.loc[mask, "OK"] = False
            df_target.loc[mask, "NOK"] = False
            df_target.loc[mask, "TROUVÉE"] = False
            m_txt = f" - Motif: {motif}" if motif else ""
            enregistrer_action_journal(op_name, "Anomalie Signalée", f"🟠 Anomalie sur Expéd {num_exp} ({transp}){m_txt}", icone="🟠", importance="alerte")
        elif action == "nok":
            df_target.loc[mask, "NOK"] = True
            df_target.loc[mask, "ANOMALIE"] = motif
            df_target.loc[mask, "OK"] = False
            df_target.loc[mask, "ANOMALIE_CHECK"] = False
            df_target.loc[mask, "TROUVÉE"] = False
            m_txt = f" - Motif: {motif}" if motif else ""
            enregistrer_action_journal(op_name, "Alerte Pointage", f"🔴 NOK sur Expéd {num_exp} ({transp}){m_txt}", icone="🔴", importance="alerte")
            
        df_target.loc[mask, "MODIFIE_PAR"] = op_name
        df_target.loc[mask, "DATE_HEURE_MODIF"] = now_str
        
        # Sauvegarde
        sauvegarder_pointages_partages(df_target)
        st.session_state.processed_data = df_target
        return True
    except Exception as e:
        st.error(f"Erreur lors de la modification : {e}")
        return False

def fusionner_pointages(df_base):
    df_saved = charger_pointages_partages()
    if df_saved is not None and not df_saved.empty:
        # On remet les types booléens
        for col_bool in ["TROUVÉE", "ANOMALIE_CHECK", "OK", "NOK"]:
            if col_bool in df_saved.columns:
                df_saved[col_bool] = df_saved[col_bool].astype(str).str.lower().isin(["true", "1"])
                
        # Clé de fusion : priorité à REF_KEY (identifiant unique d'origine)
        if "REF_KEY" in df_saved.columns and "REF_KEY" in df_base.columns:
            df_base["_cle_join"] = df_base["REF_KEY"].astype(str)
            df_saved["_cle_join"] = df_saved["REF_KEY"].astype(str)
        else:
            df_base["_cle_join"] = df_base["NUMERO EXPEDITION"].astype(str) + "_" + df_base["DESTINATION"].astype(str)
            df_saved["_cle_join"] = df_saved["NUMERO EXPEDITION"].astype(str) + "_" + df_saved["DESTINATION"].astype(str)
        
        map_cols = ["HORAIRE", "STATUT", "CARISTE_ASSIGNE", "QUAI_CONSIGNE", "TROUVÉE", "ANOMALIE_CHECK", "OK", "NOK", "ANOMALIE", "GESTIONNAIRE", "Caisses", "MODIFIE_PAR", "DATE_HEURE_MODIF"]
        df_saved_dedup = df_saved.drop_duplicates(subset=["_cle_join"])
        
        df_merged = df_base.merge(df_saved_dedup[["_cle_join"] + [c for c in map_cols if c in df_saved_dedup.columns]], on="_cle_join", how="left", suffixes=("", "_partage"))
        
        for c in map_cols:
            if f"{c}_partage" in df_merged.columns:
                df_merged[c] = df_merged[f"{c}_partage"].combine_first(df_merged[c])
                df_merged.drop(columns=[f"{c}_partage"], inplace=True)
                
        df_merged.drop(columns=["_cle_join"], inplace=True)
        
        # Recalcul de sécurité de la clé Tri (les horaires 00:00 toujours en fin de liste)
        def recompute_tri(h):
            m = re.search(r'(\d{1,2})', str(h))
            if m:
                hh = m.group(1).zfill(2)
                if hh == "00":
                    return 9999
                return int(hh + "00")
            return 9999
        df_merged["Tri"] = df_merged["HORAIRE"].apply(recompute_tri)
        return df_merged
    return df_base

