                def make_cube(x, y, z_base, dx, dy, dz, color, name, hovertext):
                    x0, x1 = x - dx/2, x + dx/2
                    y0, y1 = y - dy/2, y + dy/2
                    z0, z1 = z_base, z_base + dz
                    
                    vertices_x = [x0, x1, x1, x0, x0, x1, x1, x0]
                    vertices_y = [y0, y0, y1, y1, y0, y0, y1, y1]
